 percentage:()=>form(mount,[sel('mode','What would you like to find?',[['of','What is A% of B?'],['is','A is what percent of B?'],['change','Percentage change from A to B']],'of'),num('a','Value A',15),num('b','Value B',200)],v=>{let a=+v.a,b=+v.b,r;if(v.mode==='of')r=a/100*b;else{need(v.mode==='is'?b!==0:a!==0,'The base value cannot be zero.');r=v.mode==='is'?a/b*100:(b-a)/Math.abs(a)*100;}show({label:v.mode==='of'?'Percentage of value':v.mode==='is'?'Percentage':'Percentage change',value:n(r)+(v.mode==='of'?'':'%'),copy:String(r)});}),
 discount:()=>form(mount,[num('price','Original price',2500,0),num('discount','Discount (%)',15,0,100),num('tax','Tax after discount (%)',13,0,100),currency()],v=>{const saved=+v.price*+v.discount/100,sub=+v.price-saved,tax=sub*+v.tax/100;show({label:'Final price',value:money(sub+tax,v.currency),details:[['You save',money(saved,v.currency)],['Price after discount',money(sub,v.currency)],['Tax added',money(tax,v.currency)]],copy:money(sub+tax,v.currency)});}),
 loan:()=>form(mount,[num('principal','Loan amount',500000,1,1e12),num('rate','Annual interest rate (%)',10,0,100),num('months','Loan term (months)',60,1,1200,1),currency()],v=>{const r=loan(+v.principal,+v.rate,+v.months);show({label:'Monthly payment',value:money(r.payment,v.currency),details:[['Principal',money(+v.principal,v.currency)],['Total interest',money(r.interest,v.currency)],['Total repayment',money(r.total,v.currency)]],html:`<div class="breakdown-bar" aria-hidden="true"><i style="width:${+v.principal/r.total*100}%"></i><i style="flex:1"></i></div>`,copy:money(r.payment,v.currency),note:'Estimate for a fixed rate, reducing balance loan. Fees, insurance and lender rounding are excluded.'});}),
 compound:()=>form(mount,[num('principal','Starting amount',100000,0,1e12),num('monthly','Monthly contribution',5000,0,1e9),num('rate','Annual interest rate (%)',7,0,100),num('years','Years to grow',10,0,100),sel('frequency','Compounding',[['12','Monthly'],['1','Yearly'],['4','Quarterly'],['365','Daily']],'12'),currency()],v=>{const r=compound(+v.principal,+v.rate,+v.years,+v.monthly,+v.frequency);show({label:'Future balance',value:money(r.total,v.currency),details:[['Total contributions',money(r.invested,v.currency)],['Interest earned',money(r.interest,v.currency)]],copy:money(r.total,v.currency),note:'Assumes a constant rate and contributions at each month’s end. Taxes, fees and inflation are excluded.'});}),
 tip:()=>form(mount,[num('bill','Bill total',2400,0,1e10),num('tip','Tip (%)',10,0,100),num('people','Number of people',3,1,1000,1),currency()],v=>{const tip=+v.bill*+v.tip/100,total=+v.bill+tip;show({label:'Each person pays',value:money(total/+v.people,v.currency),details:[['Tip amount',money(tip,v.currency)],['Total with tip',money(total,v.currency)],['People sharing',v.people]],copy:money(total/+v.people,v.currency)});}),
 age:()=>{const f=form(mount,[text('birth','Date of birth','2000-01-01','date'),text('asof','Age on date',today(),'date')],v=>{const r=age(v.birth,v.asof);show({label:'Your age',value:`${r.years} years`,details:[['Calendar breakdown',`${r.years} years, ${r.months} months, ${r.days} days`],['Total days',n(r.totalDays)],['Full weeks',n(Math.floor(r.totalDays/7))]],copy:`${r.years} years, ${r.months} months, ${r.days} days`});},{label:'Calculate age',note:'Gregorian / AD dates. Monthly anniversaries clamp to the last valid day. Check official cutoff conventions separately.'});exampleButtons(f,[['Application deadline',{birth:'2006-06-15',asof:'2027-03-01'}],['Month-end example',{birth:'2026-01-31',asof:'2026-03-01'}],['Leap-day example',{birth:'2000-02-29',asof:'2025-02-28'}]]);return f;},
 'date-difference':()=>form(mount,[text('start','Start date',today(),'date'),text('end','End date',new Date(Date.now()+30*86400000).toLocaleDateString('en-CA'),'date'),sel('inclusive','Count both dates?',[['no','No — elapsed days'],['yes','Yes — inclusive count']],'no')],v=>{const diff=Math.round((dateUTC(v.end)-dateUTC(v.start))/86400000);need(diff>=0,'End date must be on or after the start date.');const days=diff+(v.inclusive==='yes'?1:0);show({label:'Time between dates',value:`${n(days)} days`,details:[['Weeks and days',`${Math.floor(days/7)} weeks, ${days%7} days`],['Hours',n(days*24)],['Counting',v.inclusive==='yes'?'Both dates included':'Elapsed days']],copy:String(days)});}),
