 bmi:()=>form(mount,[num('weight','Weight (kg)',65,.1,650),num('height','Height (cm)',170,30,300)],v=>{const bmi=+v.weight/(+v.height/100)**2;show({label:'Body mass index',value:bmi.toFixed(1),details:[['Formula','Weight (kg) ÷ height (m)²']],copy:bmi.toFixed(1),note:'For adults. BMI is a screening measure, not a diagnosis; it does not account for muscle, pregnancy or individual health. It is not a child growth calculator.'});}),
