 savings:()=>form(mount,[num('goal','Goal amount',300000,0,1e12),num('saved','Already saved',50000,0,1e12),num('months','Months to reach goal',12,1,1200,1),currency()],v=>{const left=Math.max(0,+v.goal-+v.saved);show({label:'Save each month',value:money(left/+v.months,v.currency),details:[['Still to save',money(left,v.currency)],['Time available',`${v.months} months`],['Progress',`${+v.goal?Math.min(100,+v.saved/+v.goal*100).toFixed(1):100}%`]],copy:money(left/+v.months,v.currency),note:'Simple savings plan; assumes no investment returns or interest.'});}),
 'ielts-overall':()=>{const f=form(mount,['Listening','Reading','Writing','Speaking'].map((label,i)=>sel(label.toLowerCase(),label,scoreOptions,['7.5','7.0','6.5','7.0'][i])),v=>{const scores=Object.values(v).map(Number),r=ieltsOverall(scores);show({label:'Overall IELTS band',value:r.toFixed(1),details:[['Average before rounding',(scores.reduce((a,b)=>a+b)/4).toString()],['Rounding rule','Nearest whole or half band'],['Your component scores',scores.map(x=>x.toFixed(1)).join(' · ')]],copy:r.toFixed(1),note:'Averages ending in .25 round up to the next half band; .75 rounds up to the next whole band.'});},{label:'Calculate overall band',note:'Based on the <a href="https://ielts.org/take-a-test/your-results/ielts-scoring-in-detail" target="_blank" rel="noopener">official IELTS overall scoring rule ↗</a>. Enter awarded scores in half-band steps.'});exampleButtons(f,[['6.25 → 6.5',{listening:'6.5',reading:'6.5',writing:'5.0',speaking:'7.0'}],['6.125 → 6.0',{listening:'6.5',reading:'6.5',writing:'5.5',speaking:'6.0'}],['7.75 → 8.0',{listening:'8.0',reading:'8.0',writing:'7.5',speaking:'7.5'}]]);return f;},
