 'case-converter':()=>form(mount,[area('text','Your text','a little change can make a big difference.'),sel('mode','Convert to',[['upper','UPPERCASE'],['lower','lowercase'],['title','Title Case'],['sentence','Sentence case'],['camel','camelCase'],['snake','snake_case'],['kebab','kebab-case']],'title')],v=>{const words=v.text.trim().split(/[^\p{L}\p{N}]+/u).filter(Boolean);const cap=s=>s.charAt(0).toLocaleUpperCase()+s.slice(1).toLocaleLowerCase();const vals={upper:()=>v.text.toLocaleUpperCase(),lower:()=>v.text.toLocaleLowerCase(),title:()=>v.text.toLocaleLowerCase().replace(/(^|[^\p{L}\p{N}])(\p{L})/gu,(_,prefix,letter)=>prefix+letter.toLocaleUpperCase()),sentence:()=>v.text.toLocaleLowerCase().replace(/(^\s*\p{L}|[.!?]\s+\p{L})/gu,x=>x.toLocaleUpperCase()),camel:()=>words.map((x,i)=>i?cap(x):x.toLowerCase()).join(''),snake:()=>words.join('_').toLowerCase(),kebab:()=>words.join('-').toLowerCase()};outputText(out,vals[v.mode]());},{label:'Convert text'}),
