 base64:()=>form(mount,[area('text','Text or Base64','Hello, नमस्ते!'),sel('mode','Direction',[['encode','Text → Base64'],['decode','Base64 → Text']],'encode')],v=>{let r;if(v.mode==='encode'){const b=new TextEncoder().encode(v.text);r=btoa(Array.from(b,x=>String.fromCharCode(x)).join(''));}else{const s=atob(v.text.replace(/\s/g,''));r=new TextDecoder('utf-8',{fatal:true}).decode(Uint8Array.from(s,x=>x.charCodeAt(0)));}outputText(out,r);},{label:'Convert Base64',note:'Base64 is an encoding, not encryption. This tool accepts UTF-8 text, not binary file content.'}),
