 hash:()=>form(mount,[area('text','Text to hash','A little certainty.'),sel('algorithm','Algorithm',['SHA-256','SHA-384','SHA-512'],'SHA-256')],async v=>{const data=new TextEncoder().encode(v.text),hash=crypto.subtle?await crypto.subtle.digest(v.algorithm,data):await fallbackHash(v.algorithm,data);const hex=Array.from(new Uint8Array(hash),x=>x.toString(16).padStart(2,'0')).join('');outputText(out,hex,[['Algorithm',v.algorithm],['Input size',`${data.length} bytes`]]);},{label:'Generate hash',note:'Hashes are one-way fingerprints, not encryption. Plain SHA is not suitable for storing passwords.'}),
 timestamp:()=>form(mount,[sel('mode','Convert',[['unix','Unix timestamp → UTC date'],['date','ISO date → Unix timestamp']],'unix'),text('input','Timestamp or ISO date',String(Math.floor(Date.now()/1000)),'text',true),sel('unit','Timestamp unit',[['seconds','Seconds'],['milliseconds','Milliseconds']],'seconds')],v=>{let d;if(v.mode==='unix'){need(/^-?\d+(\.\d+)?$/.test(v.input.trim()),'Enter a numeric Unix timestamp.');d=new Date(Number(v.input)*(v.unit==='seconds'?1000:1));}else{need(/(Z|[+-]\d\d:\d\d)$/i.test(v.input.trim()),'Use an ISO date with a timezone, e.g. 2026-01-01T12:00:00Z.');d=new Date(v.input);}need(Number.isFinite(+d),'That date or timestamp is outside the supported range.');show({label:v.mode==='unix'?'UTC date':'Unix timestamp',value:v.mode==='unix'?d.toISOString():String(v.unit==='seconds'?Math.floor(+d/1000):+d),details:[['UTC',d.toUTCString()],['Local time',d.toLocaleString()],['Seconds since epoch',String(Math.floor(+d/1000))],['Milliseconds',String(+d)]],copy:v.mode==='unix'?d.toISOString():String(v.unit==='seconds'?Math.floor(+d/1000):+d)});},{label:'Convert timestamp'}),
