export function setupTimer(tool,mount,out){
 const focus=tool.id==='pomodoro';let running=false,base=0,started=0,limit=25*60000,handle,laps=[];
 mount.innerHTML=`<h2>${focus?'Give one thing your attention.':'Ready when you are.'}</h2>${focus?`<div class="form-grid">${field(num('minutes','Session length (minutes)',25,1,180,1))}</div><div class="pill-row" style="margin-top:13px"><button data-preset="25" class="active">Focus · 25 min</button><button data-preset="5">Short break · 5 min</button><button data-preset="15">Long break · 15 min</button></div>`:'<p class="form-note">Precise elapsed time with laps. Works while this tool remains open.</p>'}<div class="timer-value" aria-live="off">${focus?'25:00':'00:00.00'}</div><div class="form-actions"><button class="btn primary" data-start>Start ${focus?'focus session':'stopwatch'}</button>${!focus?'<button class="btn secondary" data-lap disabled>Lap</button>':''}<button class="btn secondary" data-reset>Reset</button></div><p class="form-note">${focus?'No notification permission needed. A soft sound plays when time is up. Keep this tool open.':'Timing uses the browser’s monotonic clock.'}</p>`;
 out.innerHTML=`<h2>${focus?'A small ritual for better focus.':'Your laps'}</h2><div class="result-placeholder">${icon('clock')}<span>${focus?'Pick one task. Start the timer.<br>Let everything else wait a little.':'Start the stopwatch, then add a lap.'}</span></div>`;
 const display=mount.querySelector('.timer-value'),start=mount.querySelector('[data-start]'),lap=mount.querySelector('[data-lap]');
 const elapsed=()=>base+(running?performance.now()-started:0);
 const fmt=ms=>{ms=Math.max(0,ms);return`${String(Math.floor(ms/60000)).padStart(2,'0')}:${String(Math.floor(ms/1000)%60).padStart(2,'0')}${focus?'':'.'+String(Math.floor(ms%1000/10)).padStart(2,'0')}`;};
 function tick(){const t=elapsed();display.textContent=fmt(focus?limit-t:t);if(focus&&running&&t>=limit){running=false;base=limit;start.textContent='Start again';showDone();clearInterval(handle);}}
 function showDone(){out.innerHTML=`<h2>Session complete.</h2><div class="result-placeholder">${icon('check')}<strong>You made space for what matters.</strong><span>Stretch, drink some water, and take a break.</span></div>`;notify('Focus session complete');try{const AC=window.AudioContext||window.webkitAudioContext,ac=new AC(),o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);o.frequency.value=660;g.gain.value=.08;o.start();g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.8);o.stop(ac.currentTime+.8);o.onended=()=>ac.close();}catch{}}
 start.onclick=()=>{if(running){base=elapsed();running=false;clearInterval(handle);start.textContent='Resume';}else{if(focus){const input=mount.querySelector('[name=minutes]');if(!input.reportValidity())return;limit=+input.value*60000;if(base>=limit)base=0;input.disabled=true;}started=performance.now();running=true;handle=setInterval(tick,focus?200:35);start.textContent='Pause';}if(lap)lap.disabled=!running;};
 function reset(){clearInterval(handle);running=false;base=0;laps=[];start.textContent=focus?'Start focus session':'Start stopwatch';if(focus){mount.querySelector('[name=minutes]').disabled=false;limit=+mount.querySelector('[name=minutes]').value*60000;}if(lap)lap.disabled=true;tick();if(!focus)out.innerHTML='<h2>Your laps</h2><p class="form-note">No laps yet.</p>';}
 mount.querySelector('[data-reset]').onclick=reset;
 if(focus){mount.querySelector('[name=minutes]').oninput=()=>{if(!running)reset();};mount.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{mount.querySelector('[name=minutes]').value=b.dataset.preset;reset();mount.querySelectorAll('[data-preset]').forEach(x=>x.classList.toggle('active',x===b));});}
 if(lap)lap.onclick=()=>{laps.push(elapsed());out.innerHTML=`<h2>Your laps</h2><dl class="result-details">${laps.map((t,i)=>`<div><dt>Lap ${i+1}</dt><dd>${fmt(t)} <small>(+${fmt(t-(laps[i-1]||0))})</small></dd></div>`).reverse().join('')}</dl>`;};
 return()=>clearInterval(handle);
}
